{"filename":"lru_cache.go","content":"package main

import (
	"sync"
)

type LRUCache struct {
	size     int
	capacity int
	cache    map[int]*Node
	head     *Node
	tail     *Node
	lock     sync.Mutex
}

type Node struct {
	key   int
	value int
	prev  *Node
	next  *Node
}

func NewLRUCache(capacity int) *LRUCache {
	return &LRUCache{
		capacity: capacity,
		cache:    make(map[int]*Node),
	}
}

func (c *LRUCache) Get(key int) (int, bool) {
	c.lock.Lock()
	defer c.lock.Unlock()

	if node, ok := c.cache[key]; ok {
		c.moveToHead(node)
		return node.value, true
	}
	return 0, false
}

func (c *LRUCache) Put(key int, value int) {
	c.lock.Lock()
	defer c.lock.Unlock()

	if node, ok := c.cache[key]; ok {
		node.value = value
		c.moveToHead(node)
		return
	}

	node := &Node{key: key, value: value}
	c.cache[key] = node
	c.addToHead(node)
	c.size++

	if c.size > c.capacity {
		removed := c.removeTail()
		delete(c.cache, removed.key)
		c.size--
	}
}

func (c *LRUCache) Delete(key int) {
	c.lock.Lock()
	defer c.lock.Unlock()

	if node, ok := c.cache[key]; ok {
		c.removeNode(node)
		delete(c.cache, key)
		c.size--
	}
}

func (c *LRUCache) addToHead(node *Node) {
	node.prev = nil
	node.next = c.head
	if c.head != nil {
		c.head.prev = node
	}
	c.head = node
	if c.tail == nil {
		c.tail = node
	}
}

func (c *LRUCache) removeNode(node *Node) {
	if node.prev != nil {
		node.prev.next = node.next
	} else {
		c.head = node.next
	}

	if node.next != nil {
		node.next.prev = node.prev
	} else {
		c.tail = node.prev
	}
}

func (c *LRUCache) moveToHead(node *Node) {
	c.removeNode(node)
	c.addToHead(node)
}

func (c *LRUCache) removeTail() *Node {
	node := c.tail
	c.removeNode(node)
	return node
}"}

