import logging
import time
from functools import wraps

logger = logging.getLogger(__name__)

def retry_with_backoff(retries=4, base_delay=0.5):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            delay = base_delay
            for attempt in range(retries + 1):
                try:
                    return func(*args, **kwargs)
                except (ConnectionError, TimeoutError) as e:
                    if attempt == retries:
                        raise
                    logger.warning(f"Attempt {attempt + 1} failed: {e}. Retrying in {delay:.1f}s")
                    time.sleep(delay)
                    delay *= 2
        return wrapper
    return decorator

@retry_with_backoff()
def fetch_weather(city):
    # Simulated API call
    return {"city": city, "temp": 75}
```

This decorator retries up to 4 times (initial call + 4 retries) with exponential backoff starting at 0.5s, doubling each time. It catches only `ConnectionError` and `TimeoutError`.

