I'm working on the legacy module `legacy/order-processor.js` in our Node.js API. It uses callback hell to handle a sequence of database operations. I want to refactor it to use async/await cleanly. The current file has three functions: `getUser`, `getOrders`, and `calculateTotal`. They use callbacks with a `done` parameter. Here's the current code:

```js
function getUser(userId, done) {
  db.query('SELECT * FROM users WHERE id = ?', [userId], (err, rows) => {
    if (err) return done(err);
    done(null, rows[0]);
  });
}

function getOrders(userId, done) {
  db.query('SELECT * FROM orders WHERE user_id = ?', [userId], (err, rows) => {
    if (err) return done(err);
    done(null, rows);
  });
}

function calculateTotal(orders, done) {
  let total = orders.reduce((sum, o) => sum + o.amount, 0);
  done(null, total);
}
```

And the main flow is:
```js
function processOrder(userId, finalCallback) {
  getUser(userId, (err, user) => {
    if (err) return finalCallback(err);
    getOrders(user.id, (err, orders) => {
      if (err) return finalCallback(err);
      calculateTotal(orders, (err, total) => {
        if (err) return finalCallback(err);
        finalCallback(null, { user, orders, total });
      });
    });
  });
}
```

I want you to refactor this into an async/await version. The `db` object is a promise-based query function that returns a promise that resolves with rows. You should convert `getUser`, `getOrders`, `calculateTotal` to async functions that return promises. Also rewrite `processOrder` as an async function. Use `try/catch` for error handling. Make sure to handle the case where `user` might be undefined (if no user found).

Can you provide the refactored code and explain the changes?

Here's the refactored code using async/await:

```js
async function getUser(userId) {
  const rows = await db.query('SELECT * FROM users WHERE id = ?', [userId]);
  return rows[0];
}

async function getOrders(userId) {
  const rows = await db.query('SELECT * FROM orders WHERE user_id = ?', [userId]);
  return rows;
}

async function calculateTotal(orders) {
  return orders.reduce((sum, o) => sum + o.amount, 0);
}

async function processOrder(userId) {
  try {
    const user = await getUser(userId);
    if (!user) throw new Error('User not found');
    const orders = await getOrders(user.id);
    const total = await calculateTotal(orders);
    return { user, orders, total };
  } catch (err) {
    throw err; // rethrow to caller
  }
}
```

**Key changes:**
- Each callback-based function is now an `async function` that `await`s the db query and returns the result directly.
- `processOrder` uses `await` to sequence the calls, making the flow linear and readable.
- I added a check for `user` being undefined and throw a descriptive error.
- The outer `try/catch` catches any errors from the awaited promises and rethrows them, so the caller still gets a rejected promise.

This eliminates the nested callbacks and makes error handling centralized and cleaner.

