Our Go service `order-processor` is deadlocking after about 30 minutes of runtime. The relevant code is in `internal/worker/pool.go`. It manages a fixed pool of workers that consume jobs from a channel and send results to a results channel. The deadlock occurs intermittently when the pool is shutting down gracefully. I've attached the source file below. Please diagnose the issue and provide a fix.

```go
// internal/worker/pool.go
package worker

import (
	"context"
	"fmt"
	"sync"
)

type Job struct {
	ID   int
	Data string
}

type Result struct {
	JobID int
	Err   error
}

type Pool struct {
	jobs    chan Job
	results chan Result
	wg      sync.WaitGroup
}

func NewPool(numWorkers int, bufferSize int) *Pool {
	return &Pool{
		jobs:    make(chan Job, bufferSize),
		results: make(chan Result, bufferSize),
	}
}

func (p *Pool) Start(ctx context.Context, numWorkers int) {
	for i := 0; i < numWorkers; i++ {
		p.wg.Add(1)
		go func() {
			defer p.wg.Done()
			for {
				select {
				case <-ctx.Done():
					return
				case job, ok := <-p.jobs:
					if !ok {
						return
					}
					// Simulate work
					result := Result{JobID: job.ID}
					if job.Data == "panic" {
						result.Err = fmt.Errorf("simulated error")
					}
					p.results <- result
				}
			}
		}()
	}
}

func (p *Pool) Submit(job Job) {
	p.jobs <- job
}

func (p *Pool) Results() <-chan Result {
	return p.results
}

func (p *Pool) Close() {
	close(p.jobs)
	p.wg.Wait()
	close(p.results)
}
```

