package workerpool

import (
	"fmt"
	"sync"
)

type Pool struct {
	jobs    chan func()
	wg      sync.WaitGroup
	closeOnce sync.Once
}

func NewPool(size int) *Pool {
	p := &Pool{
		jobs: make(chan func()),
	}
	p.wg.Add(size)
	for i := 0; i < size; i++ {
		go p.worker()
	}
	return p
}

func (p *Pool) Submit(job func()) {
	p.jobs <- job
}

func (p *Pool) Close() {
	p.closeOnce.Do(func() {
		close(p.jobs)
		p.wg.Wait()
	})
}

func (p *Pool) worker() {
	defer p.wg.Done()
	for job := range p.jobs {
		job()
	}
}

package main

import (
	"fmt"
	"sync"
	"time"
	"workerpool"
)

func main() {
	pool := workerpool.NewPool(10)
	var wg sync.WaitGroup
	for i := 0; i < 1000; i++ {
		wg.Add(1)
		pool.Submit(func() {
			defer wg.Done()
			time.Sleep(time.Millisecond)
		})
	}
	wg.Wait()
	pool.Close()
	fmt.Println("All jobs completed")
}

