#!/usr/bin/env python3
import argparse
import pandas as pd
from datetime import datetime, timedelta

def validate(file_path):
    df = pd.read_csv(file_path)
    if not (len(df) >= 1000 and len(df) <= 50000):
        raise AssertionError(f"Row count {len(df)} not between 1000 and 50000")
    if df['customer_id'].isnull().any():
        raise AssertionError("customer_id contains nulls")
    if (df['revenue'] < 0).any():
        raise AssertionError("revenue has negative values")
    try:
        dates = pd.to_datetime(df['transaction_date'], format='%Y-%m-%d')
    except ValueError as e:
        raise AssertionError(f"transaction_date parsing failed: {e}")
    cutoff = datetime(2024, 1, 31)
    if (dates > cutoff).any() or (dates < cutoff - timedelta(days=365)).any():
        raise AssertionError("transaction_date not within 365 days before 2024-01-31")
    print("All validation checks passed.")

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--path', default='cleaned_sales.csv')
    args = parser.parse_args()
    validate(args.path)
