  let playerX = 0;
  let playerY = 0;
  let steps = 0;
  const maxSteps = 20;
  const treasureX = 5;
  const treasureY = 5;

  const checkWin = () => playerX === treasureX && playerY === treasureY;

  for (const move of moves) {
    if (steps >= maxSteps) break;
    if (['up', 'down', 'left', 'right'].includes(move)) {
      switch (move) {
        case 'up': playerY++; break;
        case 'down': playerY--; break;
        case 'left': playerX--; break;
        case 'right': playerX++; break;
      }
      steps++;
      if (checkWin()) {
        return { status: 'win', steps, score: 100 - steps, finalPosition: [playerX, playerY] };
      }
    }
  }

